targets.expr:
# Percentil 95 solo para APIs de aplicación
histogram_quantile(0.95, 
  rate(http_server_requests_seconds_bucket{app="svc-onboarding-process-java",
    uri=~"/api/.*",status=~"2.."
  }[5m])
)

# Percentil 99 solo para APIs de aplicación
histogram_quantile(0.99, 
  rate(http_server_requests_seconds_bucket{app="svc-onboarding-process-java",
    uri=~"/api/.*",status=~"2.."
  }[5m])
)

# Percentil 50 solo para APIs de aplicación
histogram_quantile(0.50, 
  rate(http_server_requests_seconds_bucket{app="svc-onboarding-process-java",
    uri=~"/api/.*",status=~"2.."
  }[5m])
)

# Llamadas OK cuando circuit breaker está CLOSED
sum by (service) (
  rate(
    rest_adapter_circuit_breaker_calls_total{
      endpoint="call_success",
      state="CLOSED",
      app="svc-onboarding-process-java"
    }[5m]
  ) * 60
)

# Llamadas rechazadas por circuit breaker abierto
sum by (service) (
  rate(
    rest_adapter_circuit_breaker_calls_total{
      service=~"customers|products",
      endpoint="call_not_permitted",
      app="svc-onboarding-process-java" 
    }[5m]
  )
)

# Transiciones en los últimos 5 minutos
sum by (service, estado) (
  increase(
    rest_adapter_circuit_breaker_calls_total{
      service=~"customers|products",
      endpoint="state_transition",
      app="svc-onboarding-process-java"
    }[5m]
  )
)
